{
  "findings": [
    {
      "check_id": "CKV_GCP_37",
      "title": "Ensure VM disks are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_compute_disk.changeme_count_attached_disk_disk",
      "severity": "MEDIUM",
      "explanation": "The google_compute_disk resource does not specify a disk_encryption_key, meaning it relies on Google-managed encryption keys. For critical workloads or compliance requirements, using Customer-Supplied Encryption Keys (CSEK) provides better control over data security and key management."
    }
  ],
  "patched_code": "resource "google_compute_disk" "changeme_count_attached_disk_disk" {
  name                      = "changeme-count-attached-disk-disk-${count.index}"
  count                     = var.changeme_google_attached_disk_count_number_of_instances
  type                      = "pd-ssd"
  zone                      = "us-central1-a"
  size                      = 4
  physical_block_size_bytes = 4096

  disk_encryption_key {
    raw_key = var.disk_encryption_key_raw
  }
}

variable "disk_encryption_key_raw" {
  description = "A 256-bit customer-supplied encryption key, encoded in RFC 4648 base64 to encrypt this disk. Only one of kms_key_self_link and raw_key may be set."
  type        = string
  sensitive   = true
}",
  "fix_summary": "Added a `disk_encryption_key` block to the `google_compute_disk` resource to enable Customer-Supplied Encryption Keys (CSEK). Introduced a new variable `disk_encryption_key_raw` marked as sensitive to securely provide the encryption key without hardcoding it in the Terraform file."
}
